   var w=new DcP1World(new JObject{["run_id"]="v7_isolated_model_"+(++fixtureSerial),["seed"]=17,["parameters"]=parameters,["p1_world"]=g,["config"]=configuration,["p4_stage"]=true,["p3_stage"]=true,["p2_stage"]=true,["weapon_stage"]=true,["members"]=new JArray(new JObject{["player_id"]="1",["slot"]=0,["loadout_id"]=kit}),["task_requirements"]=new JObject{["1"]=new JObject{["damage:"]=100}}});
   Change(w,s=>{s["players"][0]["Room"]=1;s["players"][0]["Position"]=Point(5,9);s["players"][0]["MeleeEquipped"]=melee;s["rooms"][1]["Status"]="active";s["rooms"][1]["Wave"]=1;s["enemies"]=new JArray(new JObject{["ID"]="foe_1",["Kind"]="elite",["Room"]=1,["Position"]=Point(20,9),["TickStart"]=Point(20,9),["Origin"]=Point(20,9),["Health"]=10000,["Maximum"]=10000,["ReadyAt"]=long.MaxValue});});return w;
