   Case("queued five tile Space distance and375ms protection",()=>{var w=World();w.QueueAction("1","dodge",Input(w,Vector2.right),"q_dash");Step(w,13);var p=Own(w);Require(Math.Abs((float)p["x"]-10)<.03f,"five tile dash "+p["x"]);Require((long)p["protection_sources"]["space"]<=410&&(long)p["dodge_duration_remaining_ms"]==0,"duration");});
   Case("new range and unchanged arcs and cycles",()=>{foreach(var kit in new[]{"ranger","runesmith"}){var w=World(kit,true);w.Action("1","attack_press",Input(w));Step(w,kit=="ranger"?2:6);var a=Own(w)["melee_action"];Require(Math.Abs((float)a["range"]-(kit=="ranger"?1.333f:3.25f))<.001f,"range");Require((int)a["arc"]==(kit=="ranger"?240:270),"arc");Require((long)a["end_tick"]-(long)a["started_tick"]==(kit=="ranger"?9:21),"cycle");}});
