   Case("range modifiers combined before final rounding",()=>{var w=World(melee:true);Change(w,s=>s["players"][0]["Upgrades"]=new JArray("ranger_pierce"));w.Action("1","attack_press",Input(w));Step(w,2);Require(Math.Abs((float)Own(w)["melee_action"]["range"]-1.567f)<.0005f,"stepwise rounding");});
