   Case("rectangular trap corner differs from old circle",()=>{var b=DcV7Geometry.Profile(parameters,"ranger","down");Require(DcV7Geometry.Overlap(b.Vertices,new Vector2(0,.2f),DcV7Geometry.Rect(-.75f,-.5f,1.5f,1)),"trap body");Require(!DcV7Geometry.Overlap(b.Vertices,new Vector2(2,0),DcV7Geometry.Rect(-.75f,-.5f,1.5f,1)),"outside trap");});
